	subroutine CalcRenConst_QCD
	use global_vars
	use global_virt
	implicit none
	double complex dup1

#include "model.h"
#include "renconst.h"
!!![matching loopints.h
	double complex A0, B0i
	external A0, B0i
!!!]matching loopints.h

	dCKM1 = 0

	dSW1 = 0

#ifdef DEBUG
	DEB 'dSW1 =', dSW1
#endif

	dZAZ1 = 0

#ifdef DEBUG
	DEB 'dZAZ1 =', dZAZ1
#endif

	dZe1 = 0

#ifdef DEBUG
	DEB 'dZe1 =', dZe1
#endif

	dZW1 = 0

#ifdef DEBUG
	DEB 'dZW1 =', dZW1
#endif

	dZZZ1 = 0

#ifdef DEBUG
	DEB 'dZZZ1 =', dZZZ1
#endif

	dMf1 = 0

        dZfL1(3,1,1) = 1/(3.D0*Pi)*
     &   (Alfas*(xrat1 - 2*DBLE(B0i(bb0,MU2,0.D0,MU2)) - 
     &       2*DBLE(B0i(bb1,MU2,0.D0,MU2)) + 
     &       MU2*(4*DBLE(B0i(dbb0,MU2,0.D0,MU2)) - 
     &          4*DBLE(B0i(dbb1,MU2,0.D0,MU2)))))

#ifdef DEBUG
	DEB 'dZfL1(3,1,1) =', dZfL1(3,1,1)
#endif

        dZfL1(4,1,1) = 1/(3.D0*Pi)*
     &   (Alfas*(xrat1 - 2*DBLE(B0i(bb0,MD2,0.D0,MD2)) - 
     &       2*DBLE(B0i(bb1,MD2,0.D0,MD2)) + 
     &       MD2*(4*DBLE(B0i(dbb0,MD2,0.D0,MD2)) - 
     &          4*DBLE(B0i(dbb1,MD2,0.D0,MD2)))))

#ifdef DEBUG
	DEB 'dZfL1(4,1,1) =', dZfL1(4,1,1)
#endif

        dup1 = xrat1 - 2*DBLE(B0i(bb0,MU2,0.D0,MU2)) - 
     &   2*DBLE(B0i(bb1,MU2,0.D0,MU2))
     
        dZfR1(3,1,1) = 1/(3.D0*Pi)*
     &   (Alfas*(dup1 + MU2*
     &        (4*DBLE(B0i(dbb0,MU2,0.D0,MU2)) - 
     &          4*DBLE(B0i(dbb1,MU2,0.D0,MU2)))))
     
        dup1 = xrat1 - 2*DBLE(B0i(bb0,MD2,0.D0,MD2)) - 
     &   2*DBLE(B0i(bb1,MD2,0.D0,MD2))

        dZfR1(4,1,1) = 1/(3.D0*Pi)*
     &   (Alfas*(dup1 + MD2*
     &        (4*DBLE(B0i(dbb0,MD2,0.D0,MD2)) - 
     &          4*DBLE(B0i(dbb1,MD2,0.D0,MD2)))))
     
! bottom quark
       dZfL1(4,3,3) = dZfL1(4,1,1)
       dZfR1(4,3,3) = dZfR1(4,1,1)
       
! top quark: wave function can be anything because it is auxiliary 
! as we have no processes with external top quarks
       dZfL1(3,3,3) = 0
       dZfR1(3,3,3) = 0
       
! top mass:
        dMf1(3,3) = MT/(3.D0*Pi)*
     &   (Alfas*(xrat - 2*DBLE(B0i(bb0,MT2,0.D0,MT2)) + 
     &       2*DBLE(B0i(bb1,MT2,0.D0,MT2))))

       !print*,"qcd dZfL1(3,1,1)=",dZfL1(3,1,1)
       !print*,"qcd dZfR1(3,1,1)=",dZfR1(3,1,1)
	end
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
	subroutine CalcRenConst_EW
	use global_vars
	use global_virt
	implicit none

#include "model.h"
#include "renconst.h"
!!![matching loopints.h
	double complex A0, B0i
	external A0, B0i
!!!]matching loopints.h

	integer Gen3
	double complex dup3, dup4, dup8
	
	dCKM1 = 0

	dup4 = DBLE(A0(MW2)) - 2*DBLE(B0i(bb00,MZ2,MW2,MW2))

        dMZsq1 = Alfa/(48.D0*CW2**2*Pi*SW2)*
     &   (3*CW2*DBLE(A0(MH2)) + 3*CW2*DBLE(A0(MZ2)) - 
     &     2*(-(6*MW2*DBLE(B0i(bb0,MZ2,MH2,MZ2))) + 
     &        CW2*(-18*DBLE(B0i(bb00,MZ2,0.D0,0.D0)) + 
     &           6*DBLE(B0i(bb00,MZ2,MH2,MZ2)) - 27*CW2**2*dup4 + 
     &           6*CW2*SW2*dup4 - 3*SW2**2*dup4 + 
     &           4*CW2**2*MZ2*xrat + 
     &           6*(CW2**2*(2*MW2 + 5*MZ2) - 2*MW2*SW2**2)*
     &            DBLE(B0i(bb0,MZ2,MW2,MW2)) + 
     &           9*MZ2*DBLE(B0i(bb1,MZ2,0.D0,0.D0)) + 
     &           12*CW2**2*MZ2*DBLE(B0i(bb1,MZ2,MW2,MW2)))))

	do Gen3 = 1,3

        dMZsq1 = dMZsq1 - 
     &   Alfa/(24.D0*CW2*Pi*SW2)*
     &    (9*DBLE(A0(Mf2(4,Gen3))) - 
     &      6*DBLE(B0i(bb00,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      18*DBLE(B0i(bb00,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      18*DBLE(B0i(bb00,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &      3*(1 + SW2*(-4 + 8*SW2))*DBLE(A0(Mf2(2,Gen3))) + 
     &      (9 + SW2*(-24 + 32*SW2))*DBLE(A0(Mf2(3,Gen3))) - 
     &      12*SW2*DBLE(A0(Mf2(4,Gen3))) + 
     &      8*SW2**2*DBLE(A0(Mf2(4,Gen3))) + 
     &      24*SW2*DBLE(B0i(bb00,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      48*SW2**2*DBLE(B0i(bb00,MZ2,Mf2(2,Gen3),
     &         Mf2(2,Gen3))) + 
     &      48*SW2*DBLE(B0i(bb00,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      64*SW2**2*DBLE(B0i(bb00,MZ2,Mf2(3,Gen3),
     &         Mf2(3,Gen3))) + 
     &      24*SW2*DBLE(B0i(bb00,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &      16*SW2**2*DBLE(B0i(bb00,MZ2,Mf2(4,Gen3),
     &         Mf2(4,Gen3))) + 
     &      3*MZ2*DBLE(B0i(bb1,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      12*MZ2*SW2*DBLE(B0i(bb1,MZ2,Mf2(2,Gen3),
     &         Mf2(2,Gen3))) + 
     &      24*MZ2*SW2**2*DBLE(B0i(bb1,MZ2,Mf2(2,Gen3),
     &         Mf2(2,Gen3))) + 
     &      9*MZ2*DBLE(B0i(bb1,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      24*MZ2*SW2*DBLE(B0i(bb1,MZ2,Mf2(3,Gen3),
     &         Mf2(3,Gen3))) + 
     &      32*MZ2*SW2**2*DBLE(B0i(bb1,MZ2,Mf2(3,Gen3),
     &         Mf2(3,Gen3))) + 
     &      9*MZ2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &      12*MZ2*SW2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),
     &         Mf2(4,Gen3))) + 
     &      8*MZ2*SW2**2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),
     &         Mf2(4,Gen3))) + 
     &      3*DBLE(B0i(bb0,MZ2,Mf2(2,Gen3),Mf2(2,Gen3)))*
     &       Mf2(2,Gen3) + 
     &      9*DBLE(B0i(bb0,MZ2,Mf2(3,Gen3),Mf2(3,Gen3)))*
     &       Mf2(3,Gen3) + 
     &      9*DBLE(B0i(bb0,MZ2,Mf2(4,Gen3),Mf2(4,Gen3)))*
     &       Mf2(4,Gen3))

	enddo

#ifdef DEBUG
	DEB 'dMZsq1 =', dMZsq1
#endif

        dZAA1 = Alfa/(12.D0*Pi)*
     &   (2*xrat + 15*DBLE(B0i(bb0,0.D0,MW2,MW2)) + 
     &     6*DBLE(B0i(bb1,0.D0,MW2,MW2)) + 
     &     36*DBLE(B0i(dbb00,0.D0,MW2,MW2)))

	do Gen3 = 1,3

        dZAA1 = dZAA1 + Alfa/(3.D0*Pi)*
     &    (3*DBLE(B0i(bb1,0.D0,Mf2(2,Gen3),Mf2(2,Gen3))) + 
     &      4*DBLE(B0i(bb1,0.D0,Mf2(3,Gen3),Mf2(3,Gen3))) + 
     &      DBLE(B0i(bb1,0.D0,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &      6*DBLE(B0i(dbb00,0.D0,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      8*DBLE(B0i(dbb00,0.D0,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      2*DBLE(B0i(dbb00,0.D0,Mf2(4,Gen3),Mf2(4,Gen3))))

	enddo

#ifdef DEBUG
	DEB 'dZAA1 =', dZAA1
#endif

        dZZA1 = Alfa/(2.D0*CW*MZ2*Pi)*
     &   ((-5*CW2 + SW2)*DBLE(A0(MW2)) + 
     &      2*(MW2*DBLE(B0i(bb0,0.D0,MW2,MW2)) + 
     &         5*CW2*DBLE(B0i(bb00,0.D0,MW2,MW2)) - 
     &         SW2*DBLE(B0i(bb00,0.D0,MW2,MW2))))/SW

	do Gen3 = 1,3

        dZZA1 = dZZA1 + Alfa/(6.D0*CW*MZ2*Pi)*
     &    (3*DBLE(A0(Mf2(4,Gen3))) - 
     &       6*DBLE(B0i(bb00,0.D0,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &       12*DBLE(B0i(bb00,0.D0,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &       6*DBLE(B0i(bb00,0.D0,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &       (3 - 12*SW2)*DBLE(A0(Mf2(2,Gen3))) + 
     &       (6 - 16*SW2)*DBLE(A0(Mf2(3,Gen3))) - 
     &       4*SW2*DBLE(A0(Mf2(4,Gen3))) + 
     &       24*SW2*DBLE(B0i(bb00,0.D0,Mf2(2,Gen3),Mf2(2,Gen3))) + 
     &       32*SW2*DBLE(B0i(bb00,0.D0,Mf2(3,Gen3),Mf2(3,Gen3))) + 
     &       8*SW2*DBLE(B0i(bb00,0.D0,Mf2(4,Gen3),Mf2(4,Gen3))))/SW

	enddo

#ifdef DEBUG
	DEB 'dZZA1 =', dZZA1
#endif

        dMWsq1 = Alfa/(48.D0*CW2*Pi*SW2)*
     &   (12*MW2*SW2**2*DBLE(B0i(bb0,MW2,MW2,MZ2)) + 
     &     CW2*(3*DBLE(A0(MH2)) + 42*DBLE(A0(MW2)) + 
     &        3*DBLE(A0(MZ2)) - 12*DBLE(B0i(bb00,MW2,MH2,MW2)) - 
     &        12*DBLE(B0i(bb00,MW2,MW2,MZ2)) + 
     &        SW2*(-24*DBLE(A0(MW2)) - 
     &           96*DBLE(B0i(bb00,MW2,0.D0,MW2))) + 
     &        MW2*(-24*xrat + 12*DBLE(B0i(bb0,MW2,MH2,MW2)) + 
     &           SW2*(16*xrat - 48*DBLE(B0i(bb0,MW2,0.D0,MW2)) - 
     &              24*DBLE(B0i(bb1,MW2,0.D0,MW2)))) + 
     &        CW2*(-24*DBLE(A0(MW2)) + 36*DBLE(A0(MZ2)) - 
     &           96*DBLE(B0i(bb00,MW2,MW2,MZ2)) - 
     &           24*MZ2*DBLE(B0i(bb0,MW2,MW2,MZ2)) + 
     &           MW2*(16*xrat - 36*DBLE(B0i(bb0,MW2,MW2,MZ2)) + 
     &              24*DBLE(B0i(bb1,MW2,MW2,MZ2))))))

	do Gen3 = 1,3

        dMWsq1 = dMWsq1 - 
     &   Alfa/(4.D0*Pi*SW2)*(DBLE(A0(Mf2(2,Gen3))) + 
     &      3*DBLE(A0(Mf2(4,Gen3))) - 
     &      2*DBLE(B0i(bb00,MW2,0.D0,Mf2(2,Gen3))) - 
     &      6*DBLE(B0i(bb00,MW2,Mf2(3,Gen3),Mf2(4,Gen3))) + 
     &      MW2*DBLE(B0i(bb1,MW2,0.D0,Mf2(2,Gen3))) + 
     &      3*MW2*DBLE(B0i(bb1,MW2,Mf2(3,Gen3),Mf2(4,Gen3))) + 
     &      3*DBLE(B0i(bb0,MW2,Mf2(3,Gen3),Mf2(4,Gen3)))*
     &       Mf2(3,Gen3))

	enddo

#ifdef DEBUG
	DEB 'dMWsq1 =', dMWsq1
#endif

	dSW1 = CW2/(2.D0*MW2*MZ2)*(-(MZ2*dMWsq1) + MW2*dMZsq1)/SW

#ifdef DEBUG
	DEB 'dSW1 =', dSW1
#endif

        dZAZ1 = -(Alfa/(6.D0*CW*MZ2*Pi)*
     &     (3*SW2*dup4 + 6*MW2*SW2*DBLE(B0i(bb0,MZ2,MW2,MW2)) + 
     &        CW2*(-15*dup4 + 6*MW2*DBLE(B0i(bb0,MZ2,MW2,MW2)) + 
     &           MZ2*(2*xrat + 15*DBLE(B0i(bb0,MZ2,MW2,MW2)) + 
     &              6*DBLE(B0i(bb1,MZ2,MW2,MW2)))))/SW)

	do Gen3 = 1,3

        dZAZ1 = dZAZ1 + Alfa/(6.D0*CW*MZ2*Pi)*
     &    (-3*DBLE(A0(Mf2(4,Gen3))) + 
     &       6*DBLE(B0i(bb00,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) + 
     &       12*DBLE(B0i(bb00,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) + 
     &       6*DBLE(B0i(bb00,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &       3*(-1 + 4*SW2)*DBLE(A0(Mf2(2,Gen3))) + 
     &       2*(-3 + 8*SW2)*DBLE(A0(Mf2(3,Gen3))) + 
     &       4*SW2*DBLE(A0(Mf2(4,Gen3))) - 
     &       24*SW2*DBLE(B0i(bb00,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &       32*SW2*DBLE(B0i(bb00,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &       8*SW2*DBLE(B0i(bb00,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &       3*MZ2*DBLE(B0i(bb1,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) + 
     &       12*MZ2*SW2*DBLE(B0i(bb1,MZ2,Mf2(2,Gen3),
     &          Mf2(2,Gen3))) - 
     &       6*MZ2*DBLE(B0i(bb1,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) + 
     &       16*MZ2*SW2*DBLE(B0i(bb1,MZ2,Mf2(3,Gen3),
     &          Mf2(3,Gen3))) - 
     &       3*MZ2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &       4*MZ2*SW2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))))/
     &     SW

	enddo

#ifdef DEBUG
	DEB 'dZAZ1 =', dZAZ1
#endif

	dZe1 = -(1/(2.D0*CW)*(dZZA1*SW + CW*dZAA1))

#ifdef DEBUG
	DEB 'dZe1 =', dZe1
#endif

        dZW1 = Alfa/(12.D0*CW2*Pi*SW2)*
     &   (-(3*MW2*SW2**2*DBLE(B0i(dbb0,MW2,MW2,MZ2))) + 
     &     CW2*(3*DBLE(B0i(dbb00,MW2,MH2,MW2)) + 
     &        3*DBLE(B0i(dbb00,MW2,MW2,MZ2)) + 
     &        SW2*(2*xrat + 15*DBLE(B0i(bb0,MW2,0.D0,MW2)) + 
     &           6*DBLE(B0i(bb1,MW2,0.D0,MW2)) + 
     &           24*DBLE(B0i(dbb00,MW2,0.D0,MW2))) + 
     &        MW2*(-3*DBLE(B0i(dbb0,MW2,MH2,MW2)) + 
     &           SW2*(12*DBLE(B0i(dbb0,MW2,0.D0,MW2)) + 
     &              6*DBLE(B0i(dbb1,MW2,0.D0,MW2)))) + 
     &        CW2*(2*xrat + 9*DBLE(B0i(bb0,MW2,MW2,MZ2)) - 
     &           6*DBLE(B0i(bb1,MW2,MW2,MZ2)) + 
     &           24*DBLE(B0i(dbb00,MW2,MW2,MZ2)) + 
     &           6*MZ2*DBLE(B0i(dbb0,MW2,MW2,MZ2)) + 
     &           MW2*(9*DBLE(B0i(dbb0,MW2,MW2,MZ2)) - 
     &              6*DBLE(B0i(dbb1,MW2,MW2,MZ2))))))

	do Gen3 = 1,3

        dZW1 = dZW1 + Alfa/(4.D0*Pi*SW2)*
     &    (DBLE(B0i(bb1,MW2,0.D0,Mf2(2,Gen3))) + 
     &      3*DBLE(B0i(bb1,MW2,Mf2(3,Gen3),Mf2(4,Gen3))) - 
     &      2*DBLE(B0i(dbb00,MW2,0.D0,Mf2(2,Gen3))) - 
     &      6*DBLE(B0i(dbb00,MW2,Mf2(3,Gen3),Mf2(4,Gen3))) + 
     &      MW2*DBLE(B0i(dbb1,MW2,0.D0,Mf2(2,Gen3))) + 
     &      3*MW2*DBLE(B0i(dbb1,MW2,Mf2(3,Gen3),Mf2(4,Gen3))) + 
     &      3*DBLE(B0i(dbb0,MW2,Mf2(3,Gen3),Mf2(4,Gen3)))*
     &       Mf2(3,Gen3))

	enddo

#ifdef DEBUG
	DEB 'dZW1 =', dZW1
#endif

        dZZZ1 = Alfa/(24.D0*CW2**2*Pi*SW2)*
     &   (-(6*MW2*DBLE(B0i(dbb0,MZ2,MH2,MZ2))) + 
     &     CW2*(9*DBLE(B0i(bb1,MZ2,0.D0,0.D0)) - 
     &        18*DBLE(B0i(dbb00,MZ2,0.D0,0.D0)) + 
     &        6*DBLE(B0i(dbb00,MZ2,MH2,MZ2)) - 
     &        12*MW2*SW2**2*DBLE(B0i(dbb0,MZ2,MW2,MW2)) + 
     &        6*SW2**2*DBLE(B0i(dbb00,MZ2,MW2,MW2)) + 
     &        9*MZ2*DBLE(B0i(dbb1,MZ2,0.D0,0.D0)) + 
     &        CW2*(-(12*SW2*DBLE(B0i(dbb00,MZ2,MW2,MW2))) + 
     &           CW2*(4*xrat + 30*DBLE(B0i(bb0,MZ2,MW2,MW2)) + 
     &              12*DBLE(B0i(bb1,MZ2,MW2,MW2)) + 
     &              54*DBLE(B0i(dbb00,MZ2,MW2,MW2)) + 
     &              12*MW2*DBLE(B0i(dbb0,MZ2,MW2,MW2)) + 
     &              MZ2*(30*DBLE(B0i(dbb0,MZ2,MW2,MW2)) + 
     &                 12*DBLE(B0i(dbb1,MZ2,MW2,MW2)))))))

	do Gen3 = 1,3

        dZZZ1 = dZZZ1 + Alfa/(24.D0*CW2*Pi*SW2)*
     &    (9*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &      6*DBLE(B0i(dbb00,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      18*DBLE(B0i(dbb00,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      18*DBLE(B0i(dbb00,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &      3*(1 + SW2*(-4 + 8*SW2))*
     &       DBLE(B0i(bb1,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) + 
     &      (9 + SW2*(-24 + 32*SW2))*
     &       DBLE(B0i(bb1,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      12*SW2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &      8*SW2**2*DBLE(B0i(bb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &      24*SW2*DBLE(B0i(dbb00,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      48*SW2**2*DBLE(B0i(dbb00,MZ2,Mf2(2,Gen3),
     &         Mf2(2,Gen3))) + 
     &      48*SW2*DBLE(B0i(dbb00,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      64*SW2**2*DBLE(B0i(dbb00,MZ2,Mf2(3,Gen3),
     &         Mf2(3,Gen3))) + 
     &      24*SW2*DBLE(B0i(dbb00,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &      16*SW2**2*DBLE(B0i(dbb00,MZ2,Mf2(4,Gen3),
     &         Mf2(4,Gen3))) + 
     &      3*MZ2*DBLE(B0i(dbb1,MZ2,Mf2(2,Gen3),Mf2(2,Gen3))) - 
     &      12*MZ2*SW2*DBLE(B0i(dbb1,MZ2,Mf2(2,Gen3),
     &         Mf2(2,Gen3))) + 
     &      24*MZ2*SW2**2*DBLE(B0i(dbb1,MZ2,Mf2(2,Gen3),
     &         Mf2(2,Gen3))) + 
     &      9*MZ2*DBLE(B0i(dbb1,MZ2,Mf2(3,Gen3),Mf2(3,Gen3))) - 
     &      24*MZ2*SW2*DBLE(B0i(dbb1,MZ2,Mf2(3,Gen3),
     &         Mf2(3,Gen3))) + 
     &      32*MZ2*SW2**2*DBLE(B0i(dbb1,MZ2,Mf2(3,Gen3),
     &         Mf2(3,Gen3))) + 
     &      9*MZ2*DBLE(B0i(dbb1,MZ2,Mf2(4,Gen3),Mf2(4,Gen3))) - 
     &      12*MZ2*SW2*DBLE(B0i(dbb1,MZ2,Mf2(4,Gen3),
     &         Mf2(4,Gen3))) + 
     &      8*MZ2*SW2**2*DBLE(B0i(dbb1,MZ2,Mf2(4,Gen3),
     &         Mf2(4,Gen3))) + 
     &      3*DBLE(B0i(dbb0,MZ2,Mf2(2,Gen3),Mf2(2,Gen3)))*
     &       Mf2(2,Gen3) + 
     &      9*DBLE(B0i(dbb0,MZ2,Mf2(3,Gen3),Mf2(3,Gen3)))*
     &       Mf2(3,Gen3) + 
     &      9*DBLE(B0i(dbb0,MZ2,Mf2(4,Gen3),Mf2(4,Gen3)))*
     &       Mf2(4,Gen3))

	enddo

#ifdef DEBUG
	DEB 'dZZZ1 =', dZZZ1
#endif

	dMf1 = 0

        dZfL1(3,1,1) = Alfa/(144.D0*CW2*Pi*SW2)*
     &   (9*xrat + 18*DBLE(B0i(bb1,MU2,MU2,MZ2)) + 
     &     SW2*(-24*xrat - 48*DBLE(B0i(bb1,MU2,MU2,MZ2)) + 
     &        SW2*(16*xrat + 32*DBLE(B0i(bb1,MU2,MU2,MZ2)))) + 
     &     CW2*(18*xrat + 36*DBLE(B0i(bb1,MU2,MD2,MW2)) + 
     &        SW2*(16*xrat1 - 32*DBLE(B0i(bb0,MU2,0.D0,MU2)) - 
     &           32*DBLE(B0i(bb1,MU2,0.D0,MU2))) + 
     &        MU2*(36*DBLE(B0i(dbb1,MU2,MD2,MW2)) + 
     &           SW2*(64*DBLE(B0i(dbb0,MU2,0.D0,MU2)) - 
     &              64*DBLE(B0i(dbb1,MU2,0.D0,MU2))))) + 
     &     MU2*(18*DBLE(B0i(dbb1,MU2,MU2,MZ2)) + 
     &        SW2*(-96*DBLE(B0i(dbb0,MU2,MU2,MZ2)) - 
     &           48*DBLE(B0i(dbb1,MU2,MU2,MZ2)) + 
     &           SW2*(128*DBLE(B0i(dbb0,MU2,MU2,MZ2)) + 
     &              64*DBLE(B0i(dbb1,MU2,MU2,MZ2))))))

#ifdef DEBUG
	print*, 'dZfL1(3,1,1) =', dZfL1(3,1,1)
#endif

        dZfL1(4,1,1) = Alfa/(144.D0*CW2*Pi*SW2)*
     &   (9*xrat + 18*DBLE(B0i(bb1,MD2,MD2,MZ2)) + 
     &     SW2*(-12*xrat - 24*DBLE(B0i(bb1,MD2,MD2,MZ2)) + 
     &        SW2*(4*xrat + 8*DBLE(B0i(bb1,MD2,MD2,MZ2)))) + 
     &     CW2*(18*xrat + 36*DBLE(B0i(bb1,MD2,MU2,MW2)) + 
     &        SW2*(4*xrat1 - 8*DBLE(B0i(bb0,MD2,0.D0,MD2)) - 
     &           8*DBLE(B0i(bb1,MD2,0.D0,MD2))) + 
     &        MD2*(36*DBLE(B0i(dbb1,MD2,MU2,MW2)) + 
     &           SW2*(16*DBLE(B0i(dbb0,MD2,0.D0,MD2)) - 
     &              16*DBLE(B0i(dbb1,MD2,0.D0,MD2))))) + 
     &     MD2*(18*DBLE(B0i(dbb1,MD2,MD2,MZ2)) + 
     &        SW2*(-48*DBLE(B0i(dbb0,MD2,MD2,MZ2)) - 
     &           24*DBLE(B0i(dbb1,MD2,MD2,MZ2)) + 
     &           SW2*(32*DBLE(B0i(dbb0,MD2,MD2,MZ2)) + 
     &              16*DBLE(B0i(dbb1,MD2,MD2,MZ2))))))

#ifdef DEBUG
	DEB 'dZfL1(4,1,1) =', dZfL1(4,1,1)
#endif

! right-handed up quarks
        dup8 = xrat1 - 2*DBLE(B0i(bb0,MU2,0.D0,MU2)) - 
     &   2*DBLE(B0i(bb1,MU2,0.D0,MU2))

        dZfR1(3,1,1) = Alfa/(72.D0*CW2*Pi*SW2)*
     &   (SW2**2*(8*xrat + 16*DBLE(B0i(bb1,MU2,MU2,MZ2))) + 
     &     CW2*(8*SW2*dup8 + 
     &        MU2*(18*DBLE(B0i(dbb1,MU2,MD2,MW2)) + 
     &           SW2*(32*DBLE(B0i(dbb0,MU2,0.D0,MU2)) - 
     &              32*DBLE(B0i(dbb1,MU2,0.D0,MU2))))) + 
     &     MU2*(9*DBLE(B0i(dbb1,MU2,MU2,MZ2)) + 
     &        SW2*(-48*DBLE(B0i(dbb0,MU2,MU2,MZ2)) - 
     &           24*DBLE(B0i(dbb1,MU2,MU2,MZ2)) + 
     &           SW2*(64*DBLE(B0i(dbb0,MU2,MU2,MZ2)) + 
     &              32*DBLE(B0i(dbb1,MU2,MU2,MZ2))))))

! right-handed down quarks
        dup8 = xrat1 - 2*DBLE(B0i(bb0,MD2,0.D0,MD2)) - 
     &   2*DBLE(B0i(bb1,MD2,0.D0,MD2))

        dZfR1(4,1,1) = Alfa/(72.D0*CW2*Pi*SW2)*
     &   (SW2**2*(2*xrat + 4*DBLE(B0i(bb1,MD2,MD2,MZ2))) + 
     &     CW2*(2*SW2*dup8 + 
     &        MD2*(18*DBLE(B0i(dbb1,MD2,MU2,MW2)) + 
     &           SW2*(8*DBLE(B0i(dbb0,MD2,0.D0,MD2)) - 
     &              8*DBLE(B0i(dbb1,MD2,0.D0,MD2))))) + 
     &     MD2*(9*DBLE(B0i(dbb1,MD2,MD2,MZ2)) + 
     &        SW2*(-24*DBLE(B0i(dbb0,MD2,MD2,MZ2)) - 
     &           12*DBLE(B0i(dbb1,MD2,MD2,MZ2)) + 
     &           SW2*(16*DBLE(B0i(dbb0,MD2,MD2,MZ2)) + 
     &              8*DBLE(B0i(dbb1,MD2,MD2,MZ2))))))

!!![the Higgs
	dup3 = 16*MW2**2 + CW2*(-4*MW2*MZ2 - 2*MW2*MH2 + CW2*MH2**2)
	
        dMHsq1 = Alfa/(32.D0*CW2**2*MW2*Pi*SW2)*
     &   (dup3*DBLE(B0i(bb0,MH2,MZ2,MZ2)) - 8*MW2**2*xrat + 
     &     CW2*(4*MW2*(MH2*DBLE(B0i(bb1,MH2,MZ2,MZ2))) + 
     &        MW2*(6*DBLE(A0(MZ2)) - 4*MZ2*xrat) + 
     &        CW2*(MH2*(3*DBLE(A0(MH2)) + 2*DBLE(A0(MW2)) + 
     &              DBLE(A0(MZ2)) + 
     &              MH2*(9*DBLE(B0i(bb0,MH2,MH2,MH2)) + 
     &                 2*DBLE(B0i(bb0,MH2,MW2,MW2))) + 
     &              MW2*(-4*DBLE(B0i(bb0,MH2,MW2,MW2)) + 
     &                 8*DBLE(B0i(bb1,MH2,MW2,MW2)))) + 
     &           MW2*(12*DBLE(A0(MW2)) + 
     &              MW2*(-24*xrat + 24*DBLE(B0i(bb0,MH2,MW2,MW2))))
     &           )))

	do Gen3 = 1,3

        dMHsq1 = dMHsq1 - 
     &   (3*Alfa)/(4.D0*MW2*Pi*SW2)*
     &    ((DBLE(A0(Mf2(3,Gen3))) + 
     &         MH2*DBLE(B0i(bb1,MH2,Mf2(3,Gen3),Mf2(3,Gen3))))*
     &       Mf2(3,Gen3) + 
     &      2*DBLE(B0i(bb0,MH2,Mf2(3,Gen3),Mf2(3,Gen3)))*
     &       Mf2(3,Gen3)**2 + 
     &      Mf2(4,Gen3)*(DBLE(A0(Mf2(4,Gen3))) + 
     &         MH2*DBLE(B0i(bb1,MH2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &         2*DBLE(B0i(bb0,MH2,Mf2(4,Gen3),Mf2(4,Gen3)))*
     &          Mf2(4,Gen3)))

	enddo

#ifdef DEBUG
	DEB 'dMHsq1 =', dMHsq1
#endif

        dZH1 = -(Alfa/(32.D0*CW2**2*MW2*Pi*SW2)*
     &     (dup3*DBLE(B0i(dbb0,MH2,MZ2,MZ2)) + 
     &       CW2*(MW2*(-2*DBLE(B0i(bb0,MH2,MZ2,MZ2)) + 
     &             4*DBLE(B0i(bb1,MH2,MZ2,MZ2))) + 
     &          4*MW2*(MH2*DBLE(B0i(dbb1,MH2,MZ2,MZ2))) + 
     &          CW2*(MH2*(MH2*
     &                 (9*DBLE(B0i(dbb0,MH2,MH2,MH2)) + 
     &                   2*DBLE(B0i(dbb0,MH2,MW2,MW2))) + 
     &                MW2*(-4*DBLE(B0i(dbb0,MH2,MW2,MW2)) + 
     &                   8*DBLE(B0i(dbb1,MH2,MW2,MW2)))) + 
     &             MW2*(-4*DBLE(B0i(bb0,MH2,MW2,MW2)) + 
     &                8*DBLE(B0i(bb1,MH2,MW2,MW2)) + 
     &                24*MW2*DBLE(B0i(dbb0,MH2,MW2,MW2)))))))

	do Gen3 = 1,3

        dZH1 = dZH1 + (3*Alfa)/(4.D0*MW2*Pi*SW2)*
     &    ((DBLE(B0i(bb1,MH2,Mf2(3,Gen3),Mf2(3,Gen3))) + 
     &         MH2*DBLE(B0i(dbb1,MH2,Mf2(3,Gen3),Mf2(3,Gen3))))*
     &       Mf2(3,Gen3) + 
     &      2*DBLE(B0i(dbb0,MH2,Mf2(3,Gen3),Mf2(3,Gen3)))*
     &       Mf2(3,Gen3)**2 + 
     &      Mf2(4,Gen3)*(DBLE(B0i(bb1,MH2,Mf2(4,Gen3),
     &           Mf2(4,Gen3))) + 
     &         MH2*DBLE(B0i(dbb1,MH2,Mf2(4,Gen3),Mf2(4,Gen3))) + 
     &         2*DBLE(B0i(dbb0,MH2,Mf2(4,Gen3),Mf2(4,Gen3)))*
     &          Mf2(4,Gen3)))

	enddo

#ifdef DEBUG
	DEB 'dZH1 =', dZH1
#endif
!!!]the Higgs
      call CalcdZe_shift
      if (lDECAYV1_NLO_EW.or.lDECAYV2_NLO_EW) then
       call CalcRenConst_EW_leptons
      else if (lBOTBOT) then
       call CalcRenConst_EW_bottom
      endif
	end
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! DelAlf in 4-dim (using D->4 in FormCalc, SM; same as D-Dim)

	subroutine CalcdZe_shift
	use global_vars
	use global_virt
	implicit none

#include "model.h"
#include "renconst.h"
!!![matching loopints.h
	double complex A0, B0i
	external A0, B0i
!!!]matching loopints.h

	integer Cha2, Cha3, Cha4, Gen2, Gen3, Neu2, Neu3, Neu4, Sfe2
	integer Sfe3, Sfe4	

	double complex DelR, DelAlf, DelRho, SigAA0, SigAAMZ
	double complex dup2

      IF (input_scheme.eq.2) THEN
        SigAA0 = -(Alfa/(3.D0*Pi)*
     -     (DBLE(B0i(bb1,0.D0,MB2,MB2)) + 
     -       4*DBLE(B0i(bb1,0.D0,MC2,MC2)) + 
     -       DBLE(B0i(bb1,0.D0,MD2,MD2)) + 
     -       3*DBLE(B0i(bb1,0.D0,ME2,ME2)) + 
     -       3*DBLE(B0i(bb1,0.D0,ML2,ML2)) + 
     -       3*DBLE(B0i(bb1,0.D0,MM2,MM2)) + 
     -       DBLE(B0i(bb1,0.D0,MS2,MS2)) + 
     -       4*DBLE(B0i(bb1,0.D0,MU2,MU2)) - 
     -       2*DBLE(B0i(dbb00,0.D0,MB2,MB2)) - 
     -       8*DBLE(B0i(dbb00,0.D0,MC2,MC2)) - 
     -       2*DBLE(B0i(dbb00,0.D0,MD2,MD2)) - 
     -       6*DBLE(B0i(dbb00,0.D0,ME2,ME2)) - 
     -       6*DBLE(B0i(dbb00,0.D0,ML2,ML2)) - 
     -       6*DBLE(B0i(dbb00,0.D0,MM2,MM2)) - 
     -       2*DBLE(B0i(dbb00,0.D0,MS2,MS2)) - 
     -       8*DBLE(B0i(dbb00,0.D0,MU2,MU2))))

        SigAAMZ = -(Alfa/(3.D0*MZ2*Pi)*
     -     (DBLE(A0(MB2)) + 4*DBLE(A0(MC2)) + DBLE(A0(MD2)) + 
     -       3*DBLE(A0(ME2)) + 3*DBLE(A0(ML2)) + 3*DBLE(A0(MM2)) + 
     -       DBLE(A0(MS2)) + 4*DBLE(A0(MU2)) - 
     -       2*DBLE(B0i(bb00,MZ2,MB2,MB2)) - 
     -       8*DBLE(B0i(bb00,MZ2,MC2,MC2)) - 
     -       2*DBLE(B0i(bb00,MZ2,MD2,MD2)) - 
     -       6*DBLE(B0i(bb00,MZ2,ME2,ME2)) - 
     -       6*DBLE(B0i(bb00,MZ2,ML2,ML2)) - 
     -       6*DBLE(B0i(bb00,MZ2,MM2,MM2)) - 
     -       2*DBLE(B0i(bb00,MZ2,MS2,MS2)) - 
     -       8*DBLE(B0i(bb00,MZ2,MU2,MU2)) + 
     -       MZ2*(DBLE(B0i(bb1,MZ2,MB2,MB2)) + 
     -          4*DBLE(B0i(bb1,MZ2,MC2,MC2)) + 
     -          DBLE(B0i(bb1,MZ2,MD2,MD2)) + 
     -          3*DBLE(B0i(bb1,MZ2,ME2,ME2)) + 
     -          3*DBLE(B0i(bb1,MZ2,ML2,ML2)) + 
     -          3*DBLE(B0i(bb1,MZ2,MM2,MM2)) + 
     -          DBLE(B0i(bb1,MZ2,MS2,MS2)) + 
     -          4*DBLE(B0i(bb1,MZ2,MU2,MU2)))))

	DelAlf = SigAA0 - SigAAMZ

	dZe1 = dZe1 - 0.5D0*DelAlf

      ENDIF

      IF (input_scheme.eq.1) THEN
! SM only
        dup2 = Alfa/(16.D0*CW2*Pi*SW2)*
     -   (4*MW2*SW2**2*DBLE(B0i(bb0,0.D0,MW2,MZ2)) + 
     -     CW2*(DBLE(A0(MH2)) + 14*DBLE(A0(MW2)) + DBLE(A0(MZ2)) - 
     -        4*DBLE(B0i(bb00,0.D0,MH2,MW2)) - 
     -        4*DBLE(B0i(bb00,0.D0,MW2,MZ2)) + 
     -        SW2*(-8*DBLE(A0(MW2)) - 
     -           32*DBLE(B0i(bb00,0.D0,0.D0,MW2))) + 
     -        MW2*(-8*xrat + 4*DBLE(B0i(bb0,0.D0,MH2,MW2)) + 
     -           SW2*(8*xrat + 4*DBLE(B0i(bb0,0.D0,0.D0,MW2)))) + 
     -        CW2*(8*MW2*xrat - 8*DBLE(A0(MW2)) + 12*DBLE(A0(MZ2)) - 
     -           32*DBLE(B0i(bb00,0.D0,MW2,MZ2)) - 
     -           8*MZ2*DBLE(B0i(bb0,0.D0,MW2,MZ2)))))

	do Gen3 = 1,3

        dup2 = dup2 - Alfa/(4.D0*Pi*SW2)*
     -    (DBLE(A0(Mf2(2,Gen3))) + 3*DBLE(A0(Mf2(4,Gen3))) - 
     -      2*DBLE(B0i(bb00,0.D0,0.D0,Mf2(2,Gen3))) - 
     -      6*DBLE(B0i(bb00,0.D0,Mf2(3,Gen3),Mf2(4,Gen3))) + 
     -      3*DBLE(B0i(bb0,0.D0,Mf2(3,Gen3),Mf2(4,Gen3)))*Mf2(3,Gen3)
     -      )

	enddo
	
c	dSW1 = CW2/(2.D0*MW2*MZ2)*(-(MZ2*dMWsq1) + MW2*dMZsq1)/SW

	DelR = dup2/MW2 + 
     &  Alfa*(6+(7-4*SW2)/(2*SW2)*log(CW2))/(4*Pi*SW2)*xrat
     &  -2*dSW1/sqrt(SW2)-dMWsq1/MW2-dZAA1+CW*dZZA1/sqrt(SW2)	


cc	dZAA1 = dZAA1 + DelR
	dZe1 = dZe1 - 0.5D0*DelR


      ENDIF
	end
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
	subroutine CalcRenConst_EW_leptons
	use global_vars
	use global_virt
	implicit none

#include "model.h"
#include "renconst.h"
!!![matching loopints.h
	double complex A0, B0i
	external A0, B0i
!!!]matching loopints.h
       double complex dup5, dup7, dup8

!!![leptons
! electron neutrino
        dZfL1(1,1,1) = Alfa/(16.D0*CW2*Pi*SW2)*
     &   (xrat + 2*DBLE(B0i(bb1,0.D0,0.D0,MZ2)) + 
     &     CW2*(2*xrat + 4*DBLE(B0i(bb1,0.D0,ME2,MW2))))

#ifdef DEBUG
	DEB 'dZfL1(1,1,1) =', dZfL1(1,1,1)
#endif
! electron
        dZfL1(2,1,1) = Alfa/(16.D0*CW2*Pi*SW2)*
     &   (xrat + 2*CW2*xrat - 4*SW2*xrat + 4*SW2**2*xrat + 
     &     4*CW2*DBLE(B0i(bb1,ME2,0.D0,MW2)) + 
     &     2*(1 - 2*SW2)**2*DBLE(B0i(bb1,ME2,ME2,MZ2)) - 
     &     16*ME2*SW2*DBLE(B0i(dbb0,ME2,ME2,MZ2)) + 
     &     32*ME2*SW2**2*DBLE(B0i(dbb0,ME2,ME2,MZ2)) + 
     &     4*CW2*ME2*DBLE(B0i(dbb1,ME2,0.D0,MW2)) + 
     &     2*ME2*DBLE(B0i(dbb1,ME2,ME2,MZ2)) - 
     &     8*ME2*SW2*DBLE(B0i(dbb1,ME2,ME2,MZ2)) + 
     &     16*ME2*SW2**2*DBLE(B0i(dbb1,ME2,ME2,MZ2)))
***[with photon loop
        dZfL1(2,1,1) = dZfL1(2,1,1) + Alfa/(4.D0*Pi)*
     &   (xrat1 - 2*DBLE(B0i(bb0,ME2,0.D0,ME2)) - 
     &     2*DBLE(B0i(bb1,ME2,0.D0,ME2)) + 
     &     ME2*(4*DBLE(B0i(dbb0,ME2,0.D0,ME2)) - 
     &        4*DBLE(B0i(dbb1,ME2,0.D0,ME2))))
***]with photon loop
#ifdef DEBUG
	DEB 'dZfL1(2,1,1) =', dZfL1(2,1,1)
#endif
! left-handed muon
        dup5 = -((Alfa*MM)/(8.D0*CW2*Pi*SW2)*
     &     (2*CW2*DBLE(B0i(dbb1,MM2,0.D0,MW2)) + 
     &       (1 + SW2*(-4 + 8*SW2))*DBLE(B0i(dbb1,MM2,MM2,MZ2))))

        dZfL1(2,2,2) = 1/(16.D0*CW2*Pi*SW2)*
     &   (-(16*CW2*MM*Pi*SW2*dup5) + Alfa*xrat + 
     &     2*Alfa*CW2*xrat - 4*Alfa*SW2*xrat + 
     &     4*Alfa*SW2**2*xrat + 
     &     4*Alfa*CW2*DBLE(B0i(bb1,MM2,0.D0,MW2)) + 
     &     2*Alfa*(1 - 2*SW2)**2*DBLE(B0i(bb1,MM2,MM2,MZ2)) - 
     &     16*Alfa*MM2*SW2*DBLE(B0i(dbb0,MM2,MM2,MZ2)) + 
     &     32*Alfa*MM2*SW2**2*DBLE(B0i(dbb0,MM2,MM2,MZ2)))
***[only photon
	dup7 = DBLE(B0i(bb0,MM2,0.D0,MM2)) + DBLE(B0i(bb1,MM2,0.D0,MM2))

        dup8 = Alfa/(4.D0*Pi)*
     &   (-2*dup7 + xrat1 + 
     &     MM2*(4*DBLE(B0i(dbb0,MM2,0.D0,MM2)) - 
     &        4*DBLE(B0i(dbb1,MM2,0.D0,MM2))))

	dZfL1(2,2,2) = dZfL1(2,2,2) + dup8
***]only photon

#ifdef DEBUG
	DEB 'dZfL1(2,2,2) =', dZfL1(2,2,2)
#endif
! right-handed muon
        dZfR1(2,2,2) = 1/(4.D0*CW2*Pi)*
     &   (-(4*CW2*MM*Pi*dup5) + 
     &     Alfa*(SW2*(xrat + 2*DBLE(B0i(bb1,MM2,MM2,MZ2))) + 
     &        MM2*(-4*DBLE(B0i(dbb0,MM2,MM2,MZ2)) + 
     &           8*SW2*DBLE(B0i(dbb0,MM2,MM2,MZ2)))))

***[only photon
	dZfR1(2,2,2) = dZfR1(2,2,2) + dup8
***]only photon
#ifdef DEBUG
	DEB 'dZfR1(2,2,2) =', dZfR1(2,2,2)
#endif
!!!]leptons
        end
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
	subroutine CalcRenConst_EW_bottom
	use global_vars
	use global_virt
	implicit none

#include "model.h"
#include "renconst.h"
!!![matching loopints.h
	double complex A0, B0i
	external A0, B0i
!!!]matching loopints.h
       double complex dup4
!!![bottom wave functions
        dMf1(4,3) = (Alfa*MB)/(288.D0*CW2*MW2*Pi*SW2)*
     &   (CW2*(MT2*(-36*DBLE(B0i(bb0,MB2,MT2,MW2)) - 
     &           18*DBLE(B0i(bb1,MB2,MT2,MW2))) + 
     &        MB2*(18*DBLE(B0i(bb0,MB2,MB2,MH2)) - 
     &           18*DBLE(B0i(bb0,MB2,MB2,MZ2)) - 
     &           18*DBLE(B0i(bb1,MB2,MB2,MH2)) - 
     &           18*DBLE(B0i(bb1,MB2,MB2,MZ2)) - 
     &           18*DBLE(B0i(bb1,MB2,MT2,MW2))) + 
     &        MW2*(-18*xrat - 36*DBLE(B0i(bb1,MB2,MT2,MW2)) + 
     &           SW2*(8*xrat - 16*DBLE(B0i(bb0,MB2,0.D0,MB2)) + 
     &              16*DBLE(B0i(bb1,MB2,0.D0,MB2))))) + 
     &     MW2*(-9*xrat - 18*DBLE(B0i(bb1,MB2,MB2,MZ2)) + 
     &        SW2*(-12*xrat + 48*DBLE(B0i(bb0,MB2,MB2,MZ2)) + 
     &           24*DBLE(B0i(bb1,MB2,MB2,MZ2)) + 
     &           SW2*(8*xrat - 32*DBLE(B0i(bb0,MB2,MB2,MZ2)) - 
     &              16*DBLE(B0i(bb1,MB2,MB2,MZ2))))))

        dup4 = xrat1 - 2*DBLE(B0i(bb0,MB2,0.D0,MB2)) - 
     &   2*DBLE(B0i(bb1,MB2,0.D0,MB2))

        dZfL1(4,3,3) = Alfa/(144.D0*CW2*MW2*Pi*SW2)*
     &   (4*CW2*MW2*SW2*dup4 + 9*MW2*xrat1 + 18*CW2*MW2*xrat1 - 
     &     12*MW2*SW2*xrat1 + 4*MW2*SW2**2*xrat1 + 
     &     9*CW2*MB2*DBLE(B0i(bb1,MB2,MB2,MH2)) + 
     &     (9*CW2*MB2 + 2*MW2*(3 - 2*SW2)**2)*
     &      DBLE(B0i(bb1,MB2,MB2,MZ2)) + 
     &     18*CW2*MT2*DBLE(B0i(bb1,MB2,MT2,MW2)) + 
     &     36*CW2*MW2*DBLE(B0i(bb1,MB2,MT2,MW2)) + 
     &     16*CW2*MB2*MW2*SW2*DBLE(B0i(dbb0,MB2,0.D0,MB2)) - 
     &     18*CW2*MB2**2*DBLE(B0i(dbb0,MB2,MB2,MH2)) + 
     &     18*CW2*MB2**2*DBLE(B0i(dbb0,MB2,MB2,MZ2)) - 
     &     48*MB2*MW2*SW2*DBLE(B0i(dbb0,MB2,MB2,MZ2)) + 
     &     32*MB2*MW2*SW2**2*DBLE(B0i(dbb0,MB2,MB2,MZ2)) + 
     &     36*CW2*MB2*MT2*DBLE(B0i(dbb0,MB2,MT2,MW2)) - 
     &     16*CW2*MB2*MW2*SW2*DBLE(B0i(dbb1,MB2,0.D0,MB2)) + 
     &     18*CW2*MB2**2*DBLE(B0i(dbb1,MB2,MB2,MH2)) + 
     &     18*CW2*MB2**2*DBLE(B0i(dbb1,MB2,MB2,MZ2)) + 
     &     18*MB2*MW2*DBLE(B0i(dbb1,MB2,MB2,MZ2)) - 
     &     24*MB2*MW2*SW2*DBLE(B0i(dbb1,MB2,MB2,MZ2)) + 
     &     16*MB2*MW2*SW2**2*DBLE(B0i(dbb1,MB2,MB2,MZ2)) + 
     &     18*CW2*MB2**2*DBLE(B0i(dbb1,MB2,MT2,MW2)) + 
     &     18*CW2*MB2*MT2*DBLE(B0i(dbb1,MB2,MT2,MW2)) + 
     &     36*CW2*MB2*MW2*DBLE(B0i(dbb1,MB2,MT2,MW2)))

        dZfR1(4,3,3) = Alfa/(144.D0*CW2*MW2*Pi*SW2)*
     &   (9*CW2*MB2*DBLE(B0i(bb1,MB2,MB2,MH2)) + 
     &     (9*CW2*MB2 + 8*MW2*SW2**2)*DBLE(B0i(bb1,MB2,MB2,MZ2)) + 
     &     2*(2*MW2*SW2**2*xrat1 + 
     &        MB2*MW2*(9*DBLE(B0i(dbb1,MB2,MB2,MZ2)) + 
     &           SW2*(-24*DBLE(B0i(dbb0,MB2,MB2,MZ2)) - 
     &              12*DBLE(B0i(dbb1,MB2,MB2,MZ2)) + 
     &              SW2*(16*DBLE(B0i(dbb0,MB2,MB2,MZ2)) + 
     &                 8*DBLE(B0i(dbb1,MB2,MB2,MZ2))))) + 
     &        CW2*(2*MW2*SW2*dup4 + 
     &           MB2*(9*DBLE(B0i(bb1,MB2,MT2,MW2)) + 
     &              MT2*(18*DBLE(B0i(dbb0,MB2,MT2,MW2)) + 
     &                 9*DBLE(B0i(dbb1,MB2,MT2,MW2))) + 
     &              MB2*(-9*DBLE(B0i(dbb0,MB2,MB2,MH2)) + 
     &                 9*DBLE(B0i(dbb0,MB2,MB2,MZ2)) + 
     &                 9*DBLE(B0i(dbb1,MB2,MB2,MH2)) + 
     &                 9*DBLE(B0i(dbb1,MB2,MB2,MZ2)) + 
     &                 9*DBLE(B0i(dbb1,MB2,MT2,MW2))) + 
     &              MW2*(18*DBLE(B0i(dbb1,MB2,MT2,MW2)) + 
     &                 SW2*
     &                  (8*DBLE(B0i(dbb0,MB2,0.D0,MB2)) - 
     &                    8*DBLE(B0i(dbb1,MB2,0.D0,MB2))))))))
!!!]bottom wave functions
!!![top quark
! top quark: wave function can be anything because it is auxiliary 
! as we have no processes with external top quarks
       dZfL1(3,3,3) = 0
       dZfR1(3,3,3) = 0
       
! top mass:
        dMf1(3,3) = (Alfa*MT)/(288.D0*CW2*MW2*Pi*SW2)*
     &   (CW2*(MB2*(-36*DBLE(B0i(bb0,MT2,MB2,MW2)) - 
     &           18*DBLE(B0i(bb1,MT2,MB2,MW2))) + 
     &        MT2*(36*DBLE(B0i(bb0,MT2,MH2,MT2)) - 
     &           18*DBLE(B0i(bb0,MT2,MT2,MZ2)) - 
     &           18*DBLE(B0i(bb1,MT2,MB2,MW2)) + 
     &           18*DBLE(B0i(bb1,MT2,MH2,MT2)) - 
     &           18*DBLE(B0i(bb1,MT2,MT2,MZ2))) + 
     &        MW2*(-18*xrat - 36*DBLE(B0i(bb1,MT2,MB2,MW2)) + 
     &           SW2*(32*xrat - 64*DBLE(B0i(bb0,MT2,0.D0,MT2)) + 
     &              64*DBLE(B0i(bb1,MT2,0.D0,MT2))))) + 
     &     MW2*(-9*xrat - 18*DBLE(B0i(bb1,MT2,MT2,MZ2)) + 
     &        SW2*(-24*xrat + 96*DBLE(B0i(bb0,MT2,MT2,MZ2)) + 
     &           48*DBLE(B0i(bb1,MT2,MT2,MZ2)) + 
     &           SW2*(32*xrat - 128*DBLE(B0i(bb0,MT2,MT2,MZ2)) - 
     &              64*DBLE(B0i(bb1,MT2,MT2,MZ2))))))
!!!]top quark
       end subroutine CalcRenConst_EW_bottom
